"""Card objects exactly as in docs/api/contract.md, built only from stored records.

Display values come from the core formatters applied to the stored high-precision strings; nothing
here computes a distance or a price.
"""
from __future__ import annotations

from decimal import Decimal
from typing import Iterable, Mapping

from ..core.pricing import fmt_km, fmt_usd

TRACE_NOTE = (
    "Price is computed from the unrounded distance, so displayed distance × 0.13 can differ from "
    "the displayed price by one cent."
)
MESSAGES = {
    "same_city": "Origin and destination are the same city.",
    "quote_expired": "This quote has expired. Please ask for a new quote.",
    "stale": "Route data changed since this quote. Please ask for a new quote.",
}


def leg(stored: Mapping) -> dict:
    return {
        "from": stored["from"],
        "to": stored["to"],
        "distance_display": fmt_km(stored["distance"]),
        "distance": stored["distance"],
    }


def transfers(legs: list[Mapping]) -> list[str]:
    return [l["to"] for l in legs[:-1]]


def card_state(status: str, nonce: str | None = None, ticket_id: str | None = None) -> dict:
    """Contract `CardState`. A card is bookable exactly when it carries a nonce."""
    return {"status": status, "bookable": nonce is not None, "nonce": nonce, "ticket_id": ticket_id}


def quote_card(quote: Mapping, state: dict, kind: str = "quote") -> dict:
    """`QuoteCard`, or `BookingRequestCard` with kind="booking_request" (same fields)."""
    return {
        "type": kind,
        "id": quote["id"],
        "origin": quote["origin"],
        "destination": quote["destination"],
        "legs": [leg(l) for l in quote["legs"]],
        "transfers": transfers(quote["legs"]),
        "distance_display": fmt_km(quote["distance"]),
        "price_display": fmt_usd(quote["price"]),
        "distance": quote["distance"],
        "price": quote["price"],
        "expires_at": quote["expires_at"],
        "state": state,
    }


def ticket_card(ticket: Mapping) -> dict:
    legs = ticket["legs_snapshot"]
    return {
        "type": "ticket",
        "id": ticket["id"],
        "quote_id": ticket["quote_id"],
        "origin": ticket["origin"],
        "destination": ticket["destination"],
        "legs": [leg(l) for l in legs],
        "transfers": transfers(legs),
        "distance_display": fmt_km(ticket["distance"]),
        "price_display": fmt_usd(ticket["price"]),
        "booked_at": ticket["booked_at"],
    }


def ticket_list_card(tickets: Iterable[Mapping], filter_: Mapping[str, str]) -> dict:
    cards = [ticket_card(t) for t in tickets]
    return {"type": "ticket_list", "count": len(cards), "filter": dict(filter_), "tickets": cards}


def nearest(items: Iterable) -> list[dict]:
    """`places.Nearby` records -> [{city, distance_display}], order kept (nearest first)."""
    return [{"city": n.city, "distance_display": fmt_km(n.distance)} for n in items]


def no_service_card(city: str, nearest_items: list[dict]) -> dict:
    return {"type": "no_service", "city": city, "nearest": nearest_items}


def ambiguous_city_card(query: str, candidates: list[dict]) -> dict:
    return {"type": "ambiguous_city", "query": query, "candidates": candidates}


def unknown_city_card(query: str, suggestions: Iterable[str]) -> dict:
    return {"type": "unknown_city", "query": query, "suggestions": list(suggestions)}


def notice_card(code: str, message: str | None = None) -> dict:
    return {"type": "notice", "code": code, "message": message or MESSAGES[code]}


def _number(text: str) -> int | float:
    """A stored coordinate as a JSON number. locations.db holds integers; a fractional coordinate
    is shown as a float (display only, comparisons use the stored string)."""
    value = Decimal(text)
    return int(value) if value == value.to_integral_value() else float(value)


def trace(quote: Mapping, formula: str, algorithm: str) -> dict:
    return {
        "quote_id": quote["id"],
        "formula": formula,
        "algorithm": algorithm,
        "network_fingerprint": quote["network_fingerprint"],
        "legs": [
            {
                **leg(l),
                "from_coord": [_number(v) for v in l["from_coord"]],
                "to_coord": [_number(v) for v in l["to_coord"]],
                "source": l["source"],
            }
            for l in quote["legs"]
        ],
        "distance": quote["distance"],
        "price": quote["price"],
        "distance_display": fmt_km(quote["distance"]),
        "price_display": fmt_usd(quote["price"]),
        "note": TRACE_NOTE,
    }

"""The airline service: everything the airline side can do, behind one interface.

The agent's tools (`find_city`, `quote_route`, `request_booking`, `list_tickets`) and the HTTP
layer (`book`, `trace`, `tickets`, `messages`) both go through `Airline`. It calls the
deterministic core for every route, distance and price and keeps quotes and tickets in app.db.

Booking (design §6, docs/design/state_invariants.md B1-B7) has exactly one entry point,
`Airline.book(user_id, quote_id, nonce)`. A nonce exists only for a card that was stored with an
assistant message by `post_assistant_message` (the `done` moment), is derived from
(quote, user, message) with a server secret and is never part of a tool result, so nothing the
LLM sees or says can book.
"""
from __future__ import annotations

import hashlib
import hmac
import secrets
import sqlite3
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from decimal import Decimal
from typing import Any, Iterable

from ..core import places
from ..core.network import Network, NetworkDataError, NetworkProvider
from ..core.pricing import FORMULA, InvalidPathError, price_path
from ..core.routing import ALGORITHM, Route, RouteError, cheapest_route
from ..store import Store, iso, parse_iso, records
from . import cards
from .locks import ConversationLocks

QUOTE_TTL = timedelta(minutes=15)
OPEN = ("quoted", "presented")  # the non-terminal quote states
_QUOTE_CARD_TYPES = ("quote", "booking_request")
_FILTER_KEYS = ("city", "ticket_id", "booked_after", "booked_before")


@dataclass(frozen=True)
class Result:
    """What a tool call produced.

    `code` is "ok" or a snake_case error code. `data` is the JSON-safe record for the LLM: names,
    ids and display values only, never a nonce. `cards` are contract `Card` objects for the UI;
    quote and booking-request cards in a Result are never bookable (state.nonce is null) - they
    become bookable when `post_assistant_message` stores them.
    """

    code: str
    data: dict = field(default_factory=dict)
    cards: tuple[dict, ...] = ()

    @property
    def ok(self) -> bool:
        return self.code == "ok"


class NotFound(Exception):
    """The object does not exist or belongs to another user (the two are not distinguished)."""

    code = "not_found"
    status = 404


class BookingError(Exception):
    """A refused booking. `code` / `status` are the contract's booking errors."""

    _TEXT = {
        "not_found": (404, "Quote not found."),
        "invalid_nonce": (409, "This confirmation is not valid. Reload the conversation and try again."),
        "not_presented": (409, "This quote has not been shown to you yet."),
        "expired": (409, cards.MESSAGES["quote_expired"]),
        "already_booked": (409, "This quote is already booked."),
        "stale": (409, cards.MESSAGES["stale"]),
    }

    def __init__(self, code: str, *, ticket_id: str | None = None, reason: str | None = None):
        self.code = code
        self.status, self.message = self._TEXT[code]
        self.ticket_id = ticket_id  # already_booked: the existing ticket
        self.reason = reason  # internal detail (stale), not for the user
        super().__init__(f"{code}: {self.message}")

    def as_response(self) -> dict:
        return {"error": {"code": self.code, "message": self.message}}


class Airline:
    def __init__(self, store: Store, networks: NetworkProvider, *,
                 locks: ConversationLocks | None = None, nonce_secret: bytes | None = None,
                 quote_ttl: timedelta = QUOTE_TTL):
        """`nonce_secret`: key for the confirmation nonces. Default: random per process, which
        means a restart invalidates the nonces held by open pages (reloading gets working ones).
        Time comes from `store.clock`."""
        self.store = store
        self.networks = networks
        self.locks = locks or ConversationLocks()
        self.quote_ttl = quote_ttl
        self._secret = nonce_secret or secrets.token_bytes(32)

    # ================================================================== tools (chat turn) ====
    def find_city(self, name: str) -> Result:
        """Resolve a city name. Codes: ok, unknown_city, ambiguous_city, no_service."""
        net = self.networks.current()
        res = places.resolve(net, name)
        if res.status == "unknown":
            return Result("unknown_city", {"query": res.query, "suggestions": list(res.candidates)},
                          (cards.unknown_city_card(res.query, res.candidates),))
        if res.status == "ambiguous":
            candidates = [_candidate(net, c) for c in res.candidates]
            return Result("ambiguous_city", {"query": res.query, "candidates": candidates},
                          (cards.ambiguous_city_card(res.query, candidates),))
        city = net.cities[res.city]
        data: dict[str, Any] = {
            "city": city.name,
            "served": net.is_served(city.name),
            "is_hub": city.is_hub,
            "connected_hubs": _connected_hubs(net, city.name),
            "similar_names": list(res.similar_names),
        }
        if data["served"]:
            return Result("ok", data)
        near = cards.nearest(places.nearest_served(net, city.name, k=3))
        data["nearest"] = near
        return Result("no_service", data, (cards.no_service_card(city.name, near),))

    def quote_route(self, user_id: str, conversation_id: str, origin: str, destination: str) -> Result:
        """Cheapest route between two cities, stored as an immutable quote (status `quoted`).
        Codes: ok, unknown_city, ambiguous_city, same_city, no_service, unreachable.
        Raises NotFound when the conversation is not the user's."""
        net = self.networks.current()
        route = cheapest_route(net, origin, destination)
        if isinstance(route, RouteError):
            with self.store.read() as con:
                self._require_conversation(con, user_id, conversation_id)
            return _route_error(net, route)

        now = _floor(self.store.clock())
        legs = [
            {
                "from": leg.origin,
                "to": leg.destination,
                "distance": leg.distance,
                "from_coord": _coord(net, leg.origin),
                "to_coord": _coord(net, leg.destination),
                "source": _source(net, leg.origin, leg.destination),
            }
            for leg in route.legs
        ]
        with self.store.write() as con:
            self._require_conversation(con, user_id, conversation_id)
            quote = records.insert_quote(
                con, now=iso(now), expires_at=iso(now + self.quote_ttl),
                conversation_id=conversation_id, user_id=user_id,
                origin=route.origin, destination=route.destination, legs=legs,
                distance=route.distance, price=route.price, network_fingerprint=route.fingerprint,
            )
        data = _quote_data(quote, "quoted")
        if route.similar_names:
            data["similar_names"] = {k: list(v) for k, v in route.similar_names.items()}
        return Result("ok", data, (cards.quote_card(quote, cards.card_state("quoted")),))

    def request_booking(self, user_id: str, conversation_id: str, quote_id: str) -> Result:
        """Ask for the confirm card of a quote. It never books and never returns a nonce.
        Codes: ok (booking_request card), not_found, quote_expired, stale, already_booked
        (with the ticket card)."""
        now = self.store.clock()
        with self.store.write() as con:
            quote = records.get_quote(con, quote_id)
            if quote is None or quote["user_id"] != user_id or quote["conversation_id"] != conversation_id:
                return Result("not_found", {"quote_id": quote_id})
            status = self._settle(con, quote, now)
            if status == "booked":
                ticket = records.get_ticket_for_quote(con, quote_id)
                card = cards.ticket_card(ticket)
                return Result("already_booked", {"quote_id": quote_id, "ticket_id": ticket["id"]}, (card,))
            if status == "expired":
                return Result("quote_expired", {"quote_id": quote_id}, (cards.notice_card("quote_expired"),))
            if status == "stale":
                return Result("stale", {"quote_id": quote_id}, (cards.notice_card("stale"),))
            card = cards.quote_card(quote, cards.card_state(status), kind="booking_request")
            return Result("ok", _quote_data(quote, status), (card,))

    def list_tickets(self, user_id: str, *, city: str | None = None, ticket_id: str | None = None,
                     booked_after: str | None = None, booked_before: str | None = None) -> Result:
        """The user's tickets, newest first, as a `ticket_list` card; `count` is computed here.

        Filters (all optional, combined with AND): `city` matches origin, destination or a
        transfer city, ignoring case and accents; `ticket_id` is exact; `booked_after` is
        inclusive and `booked_before` exclusive, ISO date or datetime (UTC when no offset).
        Codes: ok, bad_request (a time that cannot be parsed)."""
        given = {"city": city, "ticket_id": ticket_id, "booked_after": booked_after,
                 "booked_before": booked_before}
        filter_ = {k: str(given[k]) for k in _FILTER_KEYS if given[k] is not None}
        try:
            after = _parse_time(booked_after) if booked_after is not None else None
            before = _parse_time(booked_before) if booked_before is not None else None
        except ValueError as exc:
            return Result("bad_request", {"message": str(exc), "filter": filter_})
        key = places.fold(city) if city is not None else None
        with self.store.read() as con:
            rows = records.list_tickets(con, user_id)
        kept = []
        for t in rows:
            booked = parse_iso(t["booked_at"])
            if ticket_id is not None and t["id"] != ticket_id:
                continue
            if after is not None and booked < after:
                continue
            if before is not None and booked >= before:
                continue
            if key is not None and key not in {places.fold(c) for c in _cities(t["legs_snapshot"])}:
                continue
            kept.append(t)
        card = cards.ticket_list_card(kept, filter_)
        return Result("ok", {k: v for k, v in card.items() if k != "type"}, (card,))

    def post_assistant_message(self, user_id: str, conversation_id: str, text: str,
                               cards_: Iterable[dict] = (), guard_problems: Any = None) -> dict:
        """The `done` moment of a chat turn, in one transaction: store the assistant message and
        present its quote / booking-request cards (`quoted` -> `presented`, B2). Returns the
        contract `Message`; its quote cards now carry `state.nonce` when bookable. Send that
        message with the `done` event - the nonce must not reach the client earlier and must
        never be given to the LLM.

        Quote cards are stored by reference and re-rendered from the quote on every read.
        Raises NotFound (conversation not the user's) or ValueError (a quote card that does not
        belong to this user and conversation)."""
        now = self.store.clock()
        with self.store.write() as con:
            self._require_conversation(con, user_id, conversation_id)
            stored, quote_ids = [], []
            for card in cards_:
                if card.get("type") in _QUOTE_CARD_TYPES:
                    stored.append({"type": card["type"], "id": card["id"]})
                    quote_ids.append(card["id"])
                else:
                    stored.append(card)
            message = records.add_message(con, iso(now), conversation_id, "assistant", text,
                                          stored, guard_problems)
            for quote_id in dict.fromkeys(quote_ids):
                quote = records.get_quote(con, quote_id)
                if quote is None or quote["user_id"] != user_id or quote["conversation_id"] != conversation_id:
                    raise ValueError(f"card for a quote outside this conversation: {quote_id!r}")
                status = self._settle(con, quote, now)
                if status == "quoted":
                    records.set_quote_status(con, quote, "presented", iso(now))
                    status = "presented"
                if status == "presented":
                    records.add_quote_card(con, quote_id, message["id"], iso(now))
            return self._message_view(con, user_id, message, now)

    # ================================================================== HTTP layer ============
    def book(self, user_id: str, quote_id: str, nonce: str, *, lock_timeout: float | None = None) -> dict:
        """The only way a ticket is created: the user's click on a presented card.

        Returns `{"ticket": TicketCard, "message": Message}` (the system message appended to the
        conversation). Raises BookingError with code not_found, already_booked, expired, stale,
        not_presented or invalid_nonce (checked in that order); expired and stale are final for
        the quote. Takes the conversation lock itself - do not call it while holding that lock.
        `lock_timeout` (seconds) raises ConversationBusy instead of waiting for a running turn.
        """
        with self.store.read() as con:
            quote = records.get_quote(con, quote_id)
        if quote is None or quote["user_id"] != user_id:  # B1
            raise BookingError("not_found")
        with self.locks.hold(quote["conversation_id"], timeout=lock_timeout):
            with self.store.write() as con:  # B7: one BEGIN IMMEDIATE transaction
                outcome = self._book(con, user_id, quote_id, nonce)
        # A refusal may have changed the quote (expired / stale), so it is raised after COMMIT.
        if isinstance(outcome, BookingError):
            raise outcome
        return outcome

    def _book(self, con: sqlite3.Connection, user_id: str, quote_id: str, nonce: str) -> dict | BookingError:
        now = self.store.clock()
        quote = records.get_quote(con, quote_id)
        if quote is None or quote["user_id"] != user_id:  # B1
            return BookingError("not_found")
        status = self._settle(con, quote, now)  # B4
        if status == "booked":  # B5
            ticket = records.get_ticket_for_quote(con, quote_id)
            return BookingError("already_booked", ticket_id=ticket["id"])
        if status in ("expired", "stale"):
            return BookingError(status, reason=quote["status_reason"])
        if status != "presented":  # B2
            return BookingError("not_presented")
        message_id = self._match_nonce(con, quote, nonce)  # B3
        if message_id is None or not records.mark_nonce_used(con, quote_id, message_id, iso(now)):
            return BookingError("invalid_nonce")
        fingerprint, problem = self._recheck(quote)  # B6
        if problem is not None:
            records.set_quote_status(con, quote, "stale", iso(now), problem)
            return BookingError("stale", reason=problem)
        ticket = records.insert_ticket(con, now=iso(now), quote=quote, network_fingerprint=fingerprint,
                                       confirmed_message_id=message_id)
        records.set_quote_status(con, quote, "booked", iso(now))
        card = cards.ticket_card(ticket)
        message = records.add_message(con, iso(now), quote["conversation_id"], "system",
                                      "Ticket booked.", [card])
        return {"ticket": card, "message": self._message_view(con, user_id, message, now)}

    def trace(self, user_id: str, quote_id: str) -> dict:
        """Contract `Trace` ("how was this price computed") for one of the user's quotes."""
        with self.store.read() as con:
            quote = records.get_quote(con, quote_id)
        if quote is None or quote["user_id"] != user_id:
            raise NotFound(quote_id)
        return cards.trace(quote, FORMULA, ALGORITHM)

    def tickets(self, user_id: str) -> list[dict]:
        """All `TicketCard`s of the user, newest first (GET /api/tickets)."""
        with self.store.read() as con:
            return [cards.ticket_card(t) for t in records.list_tickets(con, user_id)]

    def messages(self, user_id: str, conversation_id: str) -> list[dict]:
        """Contract `Message` list of a conversation, oldest first, quote cards with the current
        server state (and a nonce when bookable). Raises NotFound when not the user's."""
        now = self.store.clock()
        with self.store.read() as con:
            self._require_conversation(con, user_id, conversation_id)
            return [self._message_view(con, user_id, m, now)
                    for m in records.list_messages(con, conversation_id)]

    def get_quote(self, user_id: str, quote_id: str) -> dict | None:
        """The quote as a `QuoteCard` with its current status (never bookable: no message, no
        nonce), or None when it is not the user's."""
        now = self.store.clock()
        with self.store.read() as con:
            quote = records.get_quote(con, quote_id)
            if quote is None or quote["user_id"] != user_id:
                return None
            return cards.quote_card(quote, self._state(con, quote, now))

    # ================================================================== internals =============
    def _require_conversation(self, con: sqlite3.Connection, user_id: str, conversation_id: str) -> None:
        if records.conversation_owner(con, conversation_id) != user_id:
            raise NotFound(conversation_id)

    def _expired(self, quote: dict, now: datetime) -> bool:
        return quote["status"] in OPEN and now >= parse_iso(quote["expires_at"])

    def _settle(self, con: sqlite3.Connection, quote: dict, now: datetime) -> str:
        """Current status inside a write transaction; an elapsed quote is stored as `expired`."""
        if self._expired(quote, now):
            records.set_quote_status(con, quote, "expired", iso(now), "validity elapsed")
        return quote["status"]

    def _nonce(self, quote: dict, message_id: str) -> str:
        """The confirmation nonce of the card of `quote` in `message_id`: bound to quote, user
        and message (B3). Derived, not stored: app.db alone is not enough to produce one."""
        text = "\x1f".join((quote["id"], quote["user_id"], message_id)).encode()
        return "n_" + hmac.new(self._secret, text, hashlib.sha256).hexdigest()[:32]

    def _match_nonce(self, con: sqlite3.Connection, quote: dict, nonce: Any) -> str | None:
        """The message whose presented, not yet used card of this quote carries `nonce`."""
        if not isinstance(nonce, str):
            return None
        found = None
        for card in records.quote_cards(con, quote["id"]):
            same = hmac.compare_digest(self._nonce(quote, card["message_id"]).encode(), nonce.encode())
            if same and card["nonce_used_at"] is None:
                found = card["message_id"]
        return found

    def _recheck(self, quote: dict) -> tuple[str, None] | tuple[None, str]:
        """B6. Recompute the quoted itinerary on the locations.db that is current right now
        (content hash checked, reloaded when it differs). Returns (fingerprint, None) when every
        city, coordinate, leg, distance and price equals the stored quote and the itinerary is
        still the cheapest one; otherwise (None, what differs)."""
        try:
            net = self.networks.current(strict=True)
        except NetworkDataError as exc:
            return None, f"locations.db cannot be read: {exc}"
        legs = quote["legs"]
        itinerary = _cities(legs)
        for leg in legs:
            for name, coord in ((leg["from"], leg["from_coord"]), (leg["to"], leg["to_coord"])):
                city = net.cities.get(name)
                if city is None:
                    return None, f"city no longer exists: {name}"
                if (city.x, city.y) != (Decimal(coord[0]), Decimal(coord[1])):
                    return None, f"coordinate changed: {name}"
        try:
            priced = price_path(net, itinerary)
        except InvalidPathError as exc:
            return None, f"itinerary no longer valid: {exc}"
        fresh_legs = [(l.origin, l.destination, l.distance) for l in priced.legs]
        if fresh_legs != [(l["from"], l["to"], l["distance"]) for l in legs]:
            return None, "leg distances changed"
        if (priced.distance, priced.price) != (quote["distance"], quote["price"]):
            return None, "distance or price changed"
        best = cheapest_route(net, quote["origin"], quote["destination"])
        if not isinstance(best, Route):
            return None, f"route lookup now fails: {best.code}"
        if best.cities != tuple(itinerary) or best.price != quote["price"]:
            return None, "a different route is now the cheapest"
        return net.fingerprint.id, None

    def _state(self, con: sqlite3.Connection, quote: dict, now: datetime,
               message_id: str | None = None) -> dict:
        """Contract `CardState` of the quote's card in `message_id` (Q2: always from the server's
        current quote state). Without a message the card is never bookable."""
        status = "expired" if self._expired(quote, now) else quote["status"]
        ticket_id = nonce = None
        if status == "booked":
            ticket_id = records.get_ticket_for_quote(con, quote["id"])["id"]
        elif status == "presented" and message_id is not None:
            for card in records.quote_cards(con, quote["id"]):
                if card["message_id"] == message_id and card["nonce_used_at"] is None:
                    nonce = self._nonce(quote, message_id)
        return cards.card_state(status, nonce, ticket_id)

    def _message_view(self, con: sqlite3.Connection, user_id: str, message: dict, now: datetime) -> dict:
        out = []
        for card in message["cards"]:
            if card.get("type") in _QUOTE_CARD_TYPES:
                quote = records.get_quote(con, card["id"])
                if quote is None or quote["user_id"] != user_id:
                    continue  # cannot happen through post_assistant_message; never leak a quote
                state = self._state(con, quote, now, message["id"])
                card = cards.quote_card(quote, state, kind=card["type"])
            out.append(card)
        return {"id": message["id"], "role": message["role"], "text": message["text"],
                "cards": out, "created_at": message["created_at"]}


# ---------------------------------------------------------------------- helpers ---------------
def _floor(moment: datetime) -> datetime:
    return parse_iso(iso(moment))


def _parse_time(text: str) -> datetime:
    try:
        moment = datetime.fromisoformat(str(text).strip())
    except ValueError:
        raise ValueError(f"not an ISO date or datetime: {text!r}") from None
    return moment.replace(tzinfo=timezone.utc) if moment.tzinfo is None else moment


def _cities(legs: list[dict]) -> list[str]:
    return [legs[0]["from"]] + [leg["to"] for leg in legs]


def _coord(net: Network, name: str) -> list[str]:
    city = net.cities[name]
    return [str(city.x), str(city.y)]


def _source(net: Network, a: str, b: str) -> str:
    """Which locations.db data says this flight exists."""
    ca, cb = net.cities[a], net.cities[b]
    if ca.is_hub and cb.is_hub:
        return f"hub_links({a}, {b})"
    return f"locations.connected_hubs({b if ca.is_hub else a})"


def _connected_hubs(net: Network, name: str) -> list[str]:
    """Hubs with a direct flight to the city: its connected_hubs, or for a hub its hub links."""
    city = net.cities[name]
    if not city.is_hub:
        return list(city.connected_hubs)
    return sorted(n for n in net.neighbors[name] if net.cities[n].is_hub)


def _candidate(net: Network, name: str) -> dict:
    return {"city": name, "is_hub": net.cities[name].is_hub, "connected_hubs": _connected_hubs(net, name)}


def _quote_data(quote: dict, status: str) -> dict:
    card = cards.quote_card(quote, cards.card_state(status))
    return {
        "quote_id": quote["id"],
        "origin": quote["origin"],
        "destination": quote["destination"],
        "legs": [{k: l[k] for k in ("from", "to", "distance_display")} for l in card["legs"]],
        "transfers": card["transfers"],
        "direct": len(card["legs"]) == 1,
        "distance_display": card["distance_display"],
        "price_display": card["price_display"],
        "expires_at": quote["expires_at"],
        "status": status,
    }


def _route_error(net: Network, err: RouteError) -> Result:
    if err.code == "same_city":
        return Result("same_city", {"cities": list(err.cities)}, (cards.notice_card("same_city"),))
    if err.code == "unreachable":
        a, b = err.cities
        text = f"There is no route between {a} and {b}."
        return Result("unreachable", {"cities": [a, b]}, (cards.notice_card("unreachable", text),))
    issues, out = [], []
    for issue in err.issues:
        item: dict[str, Any] = {"role": issue.role, "code": issue.code, "query": issue.query}
        if issue.code == "unknown_city":
            item["suggestions"] = list(issue.candidates)
            out.append(cards.unknown_city_card(issue.query, issue.candidates))
        elif issue.code == "ambiguous_city":
            item["candidates"] = [_candidate(net, c) for c in issue.candidates]
            out.append(cards.ambiguous_city_card(issue.query, item["candidates"]))
        else:  # no_service
            item["city"] = issue.city
            item["nearest"] = cards.nearest(issue.nearest_served)
            out.append(cards.no_service_card(issue.city, item["nearest"]))
        issues.append(item)
    return Result(err.code, {"issues": issues}, tuple(out))

"""app.db: the business database (users, conversations, messages, call logs, quotes, tickets).

Plain stdlib sqlite3, no ORM. Every operation opens its own connection, so a `Store` can be shared
between threads. Writes run inside `BEGIN IMMEDIATE` (`Store.write()`): the write lock is taken
before the first read, so a check-then-write sequence cannot interleave with another writer.

Times are ISO 8601 UTC strings with second precision (`2026-11-23T08:15:00Z`); sub-seconds are
truncated when a time is stored. The clock is injectable.
"""
from __future__ import annotations

import json
import secrets
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Iterator

Clock = Callable[[], datetime]

SCHEMA_VERSION = 1

_SCHEMA_V1 = """
CREATE TABLE users (
    id            TEXT PRIMARY KEY,
    auth_provider TEXT NOT NULL,
    provider_sub  TEXT NOT NULL,
    email         TEXT,
    display_name  TEXT NOT NULL,
    created_at    TEXT NOT NULL,
    UNIQUE (auth_provider, provider_sub)
);
CREATE TABLE conversations (
    id         TEXT PRIMARY KEY,
    user_id    TEXT NOT NULL REFERENCES users(id),
    title      TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX conversations_by_user ON conversations(user_id, updated_at);
CREATE TABLE messages (
    seq             INTEGER PRIMARY KEY AUTOINCREMENT,   -- insertion order within the database
    id              TEXT NOT NULL UNIQUE,
    conversation_id TEXT NOT NULL REFERENCES conversations(id),
    role            TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'system')),
    text            TEXT NOT NULL,
    cards           TEXT NOT NULL DEFAULT '[]',          -- json; quote cards without live state
    guard_problems  TEXT,                                -- json or NULL
    created_at      TEXT NOT NULL
);
CREATE INDEX messages_by_conversation ON messages(conversation_id, seq);
CREATE TABLE llm_calls (
    seq             INTEGER PRIMARY KEY AUTOINCREMENT,
    id              TEXT NOT NULL UNIQUE,
    conversation_id TEXT NOT NULL REFERENCES conversations(id),
    request         TEXT NOT NULL,                       -- json
    response        TEXT NOT NULL,                       -- json
    latency_ms      INTEGER,
    tokens          INTEGER,
    model           TEXT,
    created_at      TEXT NOT NULL
);
CREATE INDEX llm_calls_by_conversation ON llm_calls(conversation_id, seq);
CREATE TABLE tool_calls (
    seq        INTEGER PRIMARY KEY AUTOINCREMENT,
    id         TEXT NOT NULL UNIQUE,
    message_id TEXT NOT NULL REFERENCES messages(id),    -- the user message that triggered the turn
    name       TEXT NOT NULL,
    args       TEXT NOT NULL,                            -- json
    result     TEXT,                                     -- json
    error      TEXT,
    latency_ms INTEGER,
    created_at TEXT NOT NULL
);
CREATE INDEX tool_calls_by_message ON tool_calls(message_id, seq);
CREATE TABLE quotes (
    id                  TEXT PRIMARY KEY,
    conversation_id     TEXT NOT NULL REFERENCES conversations(id),
    user_id             TEXT NOT NULL REFERENCES users(id),
    origin              TEXT NOT NULL,
    destination         TEXT NOT NULL,
    legs                TEXT NOT NULL,                   -- json: from, to, distance, coords, source
    distance            TEXT NOT NULL,                   -- km, 30 dp decimal string
    price               TEXT NOT NULL,                   -- USD, 30 dp decimal string
    network_fingerprint TEXT NOT NULL,
    status              TEXT NOT NULL
                        CHECK (status IN ('quoted', 'presented', 'booked', 'expired', 'stale')),
    status_reason       TEXT,
    created_at          TEXT NOT NULL,
    expires_at          TEXT NOT NULL,
    presented_at        TEXT,
    closed_at           TEXT                             -- when it became booked / expired / stale
);
CREATE INDEX quotes_by_conversation ON quotes(conversation_id);
-- One row per (quote, message) whose card was sent to the user with `done`. The one-time
-- confirmation nonce of that card is derived from (quote, user, message); it is never stored.
CREATE TABLE quote_cards (
    quote_id      TEXT NOT NULL REFERENCES quotes(id),
    message_id    TEXT NOT NULL REFERENCES messages(id),
    presented_at  TEXT NOT NULL,
    nonce_used_at TEXT,
    PRIMARY KEY (quote_id, message_id)
);
CREATE TABLE tickets (
    id                   TEXT PRIMARY KEY,
    user_id              TEXT NOT NULL REFERENCES users(id),
    quote_id             TEXT NOT NULL UNIQUE REFERENCES quotes(id),   -- B5: one ticket per quote
    origin               TEXT NOT NULL,
    destination          TEXT NOT NULL,
    legs_snapshot        TEXT NOT NULL,                  -- json, same form as quotes.legs
    distance             TEXT NOT NULL,
    price                TEXT NOT NULL,
    network_fingerprint  TEXT NOT NULL,                  -- locations.db verified at booking time
    confirmed_message_id TEXT NOT NULL REFERENCES messages(id),        -- the card that was clicked
    booked_at            TEXT NOT NULL
);
CREATE INDEX tickets_by_user ON tickets(user_id, booked_at);

-- Q3: booked / expired / stale never change again, whatever the application code does.
CREATE TRIGGER quotes_terminal_status BEFORE UPDATE OF status ON quotes
WHEN OLD.status IN ('booked', 'expired', 'stale') AND NEW.status <> OLD.status
BEGIN SELECT RAISE(ABORT, 'quote status is terminal'); END;
-- B2/B7: a ticket can only be written for a quote that is `presented` in the same transaction.
CREATE TRIGGER tickets_need_presented_quote BEFORE INSERT ON tickets
WHEN (SELECT status FROM quotes WHERE id = NEW.quote_id) IS NOT 'presented'
BEGIN SELECT RAISE(ABORT, 'ticket needs a presented quote'); END;
CREATE TRIGGER tickets_are_immutable BEFORE UPDATE ON tickets
BEGIN SELECT RAISE(ABORT, 'tickets are immutable'); END;
"""

_MIGRATIONS = {1: _SCHEMA_V1}


def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def iso(moment: datetime) -> str:
    """Stored / wire form of a time. Sub-seconds are dropped (floor)."""
    if moment.tzinfo is None:
        raise ValueError("naive datetime; times must be timezone-aware")
    return moment.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_iso(text: str) -> datetime:
    return datetime.strptime(text, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)


def new_id(prefix: str) -> str:
    """Opaque id with a type prefix (`u_`, `c_`, `m_`, `q_`, `t_`, ...)."""
    return f"{prefix}_{secrets.token_hex(8)}"


def to_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


class Store:
    def __init__(self, path: str | Path, clock: Clock = utc_now):
        self.path = Path(path)
        self.clock = clock
        self.path.parent.mkdir(parents=True, exist_ok=True)
        con = self._connect()
        try:
            con.execute("PRAGMA journal_mode = WAL")  # readers are not blocked by a writer
            self._migrate(con)
        finally:
            con.close()

    def now(self) -> str:
        return iso(self.clock())

    def _connect(self) -> sqlite3.Connection:
        # isolation_level=None: no implicit transactions; `write()` issues BEGIN IMMEDIATE itself.
        con = sqlite3.connect(self.path, isolation_level=None, timeout=30)
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA foreign_keys = ON")
        return con

    def _migrate(self, con: sqlite3.Connection) -> None:
        con.execute("BEGIN IMMEDIATE")
        try:
            version = con.execute("PRAGMA user_version").fetchone()[0]
            if version > SCHEMA_VERSION:
                raise RuntimeError(f"{self.path} has schema {version}, this code knows {SCHEMA_VERSION}")
            for target in range(version + 1, SCHEMA_VERSION + 1):
                for statement in _split_statements(_MIGRATIONS[target]):
                    con.execute(statement)
                con.execute(f"PRAGMA user_version = {target}")
        except BaseException:
            con.execute("ROLLBACK")
            raise
        con.execute("COMMIT")

    @contextmanager
    def read(self) -> Iterator[sqlite3.Connection]:
        """A connection for reads; several statements see one snapshot."""
        con = self._connect()
        try:
            con.execute("BEGIN")
            try:
                yield con
            finally:
                con.execute("ROLLBACK")
        finally:
            con.close()

    @contextmanager
    def write(self) -> Iterator[sqlite3.Connection]:
        """One `BEGIN IMMEDIATE` transaction: commit on normal exit, roll back on any exception."""
        con = self._connect()
        try:
            con.execute("BEGIN IMMEDIATE")
            try:
                yield con
            except BaseException:
                con.execute("ROLLBACK")
                raise
            con.execute("COMMIT")
        finally:
            con.close()

    # --- convenience wrappers: one transaction each (see records.py for the composable forms) ---
    def upsert_user(self, auth_provider: str, provider_sub: str, display_name: str,
                    email: str | None = None) -> dict:
        from . import records

        with self.write() as con:
            return records.upsert_user(con, self.now(), auth_provider, provider_sub, display_name, email)

    def get_user(self, user_id: str) -> dict | None:
        from . import records

        with self.read() as con:
            return records.get_user(con, user_id)

    def create_conversation(self, user_id: str, title: str = "") -> dict:
        from . import records

        with self.write() as con:
            return records.create_conversation(con, self.now(), user_id, title)

    def get_conversation(self, user_id: str, conversation_id: str) -> dict | None:
        """The conversation summary, or None when it does not exist or belongs to someone else."""
        from . import records

        with self.read() as con:
            return records.get_conversation(con, user_id, conversation_id)

    def list_conversations(self, user_id: str) -> list[dict]:
        from . import records

        with self.read() as con:
            return records.list_conversations(con, user_id)

    def set_conversation_title(self, user_id: str, conversation_id: str, title: str) -> bool:
        from . import records

        with self.write() as con:
            return records.set_conversation_title(con, user_id, conversation_id, title)

    def add_message(self, conversation_id: str, role: str, text: str, cards: list | tuple = (),
                    guard_problems: Any = None) -> dict:
        """Store a message as is. Assistant messages that carry quote or booking-request cards
        must go through `Airline.post_assistant_message`, which also presents those quotes."""
        from . import records

        with self.write() as con:
            return records.add_message(con, self.now(), conversation_id, role, text, cards, guard_problems)

    def list_messages(self, conversation_id: str) -> list[dict]:
        """Raw messages, oldest first. Quote cards carry no live state here; for the contract
        `Message` form use `Airline.messages`."""
        from . import records

        with self.read() as con:
            return records.list_messages(con, conversation_id)

    def add_llm_call(self, conversation_id: str, request: Any, response: Any, *,
                     latency_ms: int | None = None, tokens: int | None = None,
                     model: str | None = None) -> str:
        from . import records

        with self.write() as con:
            return records.add_llm_call(con, self.now(), conversation_id, request, response,
                                        latency_ms, tokens, model)

    def add_tool_call(self, message_id: str, name: str, args: Any, result: Any = None, *,
                      error: str | None = None, latency_ms: int | None = None) -> str:
        from . import records

        with self.write() as con:
            return records.add_tool_call(con, self.now(), message_id, name, args, result, error, latency_ms)

    def list_llm_calls(self, conversation_id: str) -> list[dict]:
        from . import records

        with self.read() as con:
            return records.list_llm_calls(con, conversation_id)

    def list_tool_calls(self, message_id: str) -> list[dict]:
        from . import records

        with self.read() as con:
            return records.list_tool_calls(con, message_id)


def _split_statements(script: str) -> list[str]:
    """Split a schema script into statements (executescript would commit our transaction).
    Trigger bodies contain `;`, so a statement ends only where sqlite says it is complete."""
    out: list[str] = []
    buf = ""
    for line in script.splitlines(keepends=True):
        buf += line
        if sqlite3.complete_statement(buf):
            out.append(buf.strip())
            buf = ""
    if buf.strip():
        raise ValueError("incomplete statement at the end of the schema script")
    return out

"""Read-only view of locations.db: cities, hubs, flights, and a fingerprint of the file.

locations.db is the single source of truth. This module only reads it (sqlite `mode=ro`),
validates it strictly (bad data raises, nothing is silently repaired) and builds an immutable
`Network`. Nothing here is hard-coded or copied from the database.
"""
from __future__ import annotations

import hashlib
import re
import sqlite3
import threading
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Any, Iterable, Mapping

_COORD_RE = re.compile(r"-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?\Z")


class NetworkDataError(Exception):
    """locations.db is missing, unreadable or violates the documented format."""


@dataclass(frozen=True)
class Fingerprint:
    """Identity of the database file a Network was built from.

    `id` (the content hash) is what quotes store and compare; mtime/size are only the cheap
    change detector used by `NetworkProvider`.
    """

    sha256: str
    size: int
    mtime_ns: int

    @property
    def id(self) -> str:
        return f"sha256:{self.sha256}"


@dataclass(frozen=True)
class City:
    name: str
    x: Decimal
    y: Decimal
    is_hub: bool
    connected_hubs: tuple[str, ...]  # non-hub only, in database order


@dataclass(frozen=True, eq=False)
class Network:
    cities: Mapping[str, City]  # database order
    hub_links: frozenset[frozenset[str]]
    fingerprint: Fingerprint
    # Derived, filled once by `build_network`; never mutated afterwards.
    neighbors: Mapping[str, frozenset[str]] = field(repr=False, default_factory=dict)
    hubs: tuple[str, ...] = ()
    served: tuple[str, ...] = ()
    fold_index: Mapping[str, tuple[str, ...]] = field(repr=False, default_factory=dict)
    hub_paths: Mapping[tuple[str, str], tuple[tuple[str, ...], ...]] = field(
        repr=False, default_factory=dict
    )

    def has_flight(self, a: str, b: str) -> bool:
        return b in self.neighbors.get(a, ())

    def is_served(self, name: str) -> bool:
        """A city has service when at least one direct flight touches it."""
        return bool(self.neighbors.get(name))


def _fail(msg: str) -> None:
    raise NetworkDataError(msg)


def build_network(
    location_rows: Iterable[tuple[Any, Any, Any, Any]],
    link_rows: Iterable[tuple[Any, Any]],
    fingerprint: Fingerprint,
) -> Network:
    """Validate raw rows (`city_name, coordinate, is_hub, connected_hubs` and `hub_a, hub_b`)
    and build the Network. Used for the real database and for generated test graphs alike."""
    raw: list[tuple[str, Decimal, Decimal, bool, str]] = []
    seen: set[str] = set()
    for row in location_rows:
        if len(row) != 4:
            _fail(f"locations row has {len(row)} columns, expected 4")
        name, coord, is_hub, connected = row
        if not isinstance(name, str) or not name or name != name.strip() or ";" in name:
            _fail(f"bad city_name: {name!r}")
        if name in seen:
            _fail(f"duplicate city_name: {name!r}")
        seen.add(name)
        if not isinstance(coord, str) or not _COORD_RE.match(coord):
            _fail(f"bad coordinate for {name!r}: {coord!r} (expected 'x,y')")
        if isinstance(is_hub, bool) or is_hub not in (0, 1) or not isinstance(is_hub, int):
            _fail(f"bad is_hub for {name!r}: {is_hub!r} (expected 0 or 1)")
        if not isinstance(connected, str):
            _fail(f"bad connected_hubs for {name!r}: {connected!r}")
        xs, ys = coord.split(",")
        raw.append((name, Decimal(xs), Decimal(ys), bool(is_hub), connected))

    hub_names = {name for name, _, _, is_hub, _ in raw if is_hub}
    cities: dict[str, City] = {}
    adj: dict[str, set[str]] = {name: set() for name in seen}
    for name, x, y, is_hub, connected in raw:
        if is_hub:
            if connected != "":
                _fail(f"hub {name!r} must have empty connected_hubs, got {connected!r}")
            spokes: tuple[str, ...] = ()
        else:
            spokes = tuple(connected.split(";")) if connected else ()
            if len(set(spokes)) != len(spokes):
                _fail(f"duplicate hub in connected_hubs of {name!r}: {connected!r}")
            for hub in spokes:
                if hub not in seen:
                    _fail(f"connected_hubs of {name!r} names an unknown city: {hub!r}")
                if hub not in hub_names:
                    _fail(f"connected_hubs of {name!r} names a non-hub city: {hub!r}")
                adj[name].add(hub)
                adj[hub].add(name)
        cities[name] = City(name, x, y, is_hub, spokes)

    links: set[frozenset[str]] = set()
    for row in link_rows:
        if len(row) != 2:
            _fail(f"hub_links row has {len(row)} columns, expected 2")
        a, b = row
        for end in (a, b):
            if end not in seen:
                _fail(f"hub_links names an unknown city: {end!r}")
            if end not in hub_names:
                _fail(f"hub_links names a non-hub city: {end!r}")
        if a == b:
            _fail(f"hub_links has a self-loop: {a!r}")
        links.add(frozenset((a, b)))  # (a, b) and (b, a) describe the same two-way flight
        adj[a].add(b)
        adj[b].add(a)

    # Function-level imports: places and routing depend on this module.
    from .places import build_fold_index
    from .routing import build_hub_paths

    net = Network(
        cities=cities,
        hub_links=frozenset(links),
        fingerprint=fingerprint,
        neighbors={name: frozenset(ns) for name, ns in adj.items()},
        hubs=tuple(name for name in cities if cities[name].is_hub),
        served=tuple(name for name in cities if adj[name]),
        fold_index=build_fold_index(cities),
    )
    object.__setattr__(net, "hub_paths", build_hub_paths(net))
    return net


def _stat(path: Path) -> tuple[int, int]:
    try:
        st = path.stat()
    except OSError as exc:
        raise NetworkDataError(f"cannot stat {path}: {exc}") from exc
    return st.st_mtime_ns, st.st_size


def _sha256(path: Path) -> str:
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError as exc:
        raise NetworkDataError(f"cannot read {path}: {exc}") from exc


def _read_rows(path: Path) -> tuple[list[tuple], list[tuple]]:
    uri = path.resolve().as_uri() + "?mode=ro"
    try:
        con = sqlite3.connect(uri, uri=True)
        try:
            locations = con.execute(
                "SELECT city_name, coordinate, is_hub, connected_hubs FROM locations ORDER BY rowid"
            ).fetchall()
            links = con.execute("SELECT hub_a, hub_b FROM hub_links ORDER BY rowid").fetchall()
        finally:
            con.close()
    except sqlite3.Error as exc:
        raise NetworkDataError(f"cannot read {path}: {exc}") from exc
    return locations, links


def load_network(path: str | Path) -> Network:
    """Load and validate the database. The hash and the rows are taken from the same file state:
    if the file changes while it is being read, the read is repeated."""
    path = Path(path)
    for _ in range(3):
        before = _stat(path)
        digest = _sha256(path)
        locations, links = _read_rows(path)
        if _stat(path) == before and _sha256(path) == digest:
            return build_network(locations, links, Fingerprint(digest, before[1], before[0]))
    raise NetworkDataError(f"{path} keeps changing while being read")


class NetworkProvider:
    """Hands out the Network for the current content of the database file.

    `current()` stats the file on every call; when mtime or size differ from the loaded state the
    content is hashed, and the Network is rebuilt only if the hash differs too. `strict=True`
    hashes unconditionally (for booking re-validation, where a missed change is not acceptable).
    A database that became invalid raises instead of serving the previous Network.
    """

    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._lock = threading.Lock()
        self._net: Network | None = None
        self._stat: tuple[int, int] | None = None

    def current(self, strict: bool = False) -> Network:
        with self._lock:
            stat = _stat(self.path)
            if self._net is not None:
                if stat == self._stat and not strict:
                    return self._net
                if _sha256(self.path) == self._net.fingerprint.sha256 and _stat(self.path) == stat:
                    self._stat = stat
                    return self._net
            self._net = None  # never serve a stale network after a failed reload
            net = load_network(self.path)
            self._net = net
            self._stat = (net.fingerprint.mtime_ns, net.fingerprint.size)
            return net

"""Canonical distance and price computation.

`price_path` is the ONLY place in the system that turns a city sequence into a distance and a
price. Quotes, booking re-validation and tests all call it. Everything runs in an explicit Decimal
context (prec 50, ROUND_HALF_EVEN) that is created per call, so results never depend on the
calling thread's default context (28 digits).

Stored values are strings with 30 decimal places ("high-precision", not "exact": a leg distance is
exact only when dx² + dy² is a perfect square). Rounding to display precision happens only in
`fmt_km` / `fmt_usd`, and a displayed value is never fed back into a calculation.
"""
from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_EVEN, ROUND_HALF_UP, Context, Decimal
from typing import TYPE_CHECKING, Sequence

if TYPE_CHECKING:  # no runtime import: network.py depends on this module
    from .network import Network

PRECISION = 50
STORED_PLACES = 30
PRICE_PER_KM = Decimal("0.13")  # US dollars per km (take-home requirement 6)
FORMULA = (
    "price = sum(sqrt(dx^2 + dy^2)) * 0.13 USD; Decimal prec 50, ROUND_HALF_EVEN, stored to 30 dp"
)

_Q_STORED = Decimal(f"1e-{STORED_PLACES}")
_Q_KM = Decimal("0.1")
_Q_CENT = Decimal("0.01")


class InvalidPathError(ValueError):
    """The city sequence is not a bookable itinerary on this network."""


def new_context() -> Context:
    """A fresh canonical context. Fresh per computation: Context objects are mutable (flags)."""
    return Context(prec=PRECISION, rounding=ROUND_HALF_EVEN)


def point_distance(ax: Decimal, ay: Decimal, bx: Decimal, by: Decimal, ctx: Context) -> Decimal:
    """Euclidean distance in km at context precision, not quantized."""
    dx = ctx.subtract(bx, ax)
    dy = ctx.subtract(by, ay)
    return ctx.sqrt(ctx.add(ctx.multiply(dx, dx), ctx.multiply(dy, dy)))


def stored(value: Decimal, ctx: Context) -> str:
    """Quantize to the stored precision (30 dp) and render as a plain decimal string."""
    return format(value.quantize(_Q_STORED, context=ctx), "f")


@dataclass(frozen=True)
class Leg:
    origin: str
    destination: str
    distance: str  # km, 30 dp


@dataclass(frozen=True)
class Priced:
    cities: tuple[str, ...]
    legs: tuple[Leg, ...]
    distance: str  # km, 30 dp: the sum of the unrounded leg distances, quantized once
    price: str  # USD, 30 dp: unrounded distance * 0.13, quantized once

    @property
    def transfers(self) -> tuple[str, ...]:
        return self.cities[1:-1]


def price_path(net: "Network", cities: Sequence[str]) -> Priced:
    """Price an itinerary given as canonical city names, origin first.

    Refuses anything that is not bookable: unknown names, a leg that is not an operating flight,
    a transfer at a non-hub, or a city visited twice.
    """
    cities = tuple(cities)
    if len(cities) < 2:
        raise InvalidPathError("an itinerary needs at least two cities")
    if len(set(cities)) != len(cities):
        raise InvalidPathError("an itinerary cannot visit a city twice")
    for name in cities:
        if name not in net.cities:
            raise InvalidPathError(f"unknown city: {name!r}")
    for name in cities[1:-1]:
        if not net.cities[name].is_hub:
            raise InvalidPathError(f"transfer at a non-hub city: {name!r}")

    ctx = new_context()
    legs: list[Leg] = []
    total: Decimal | None = None
    for a, b in zip(cities, cities[1:]):
        if not net.has_flight(a, b):
            raise InvalidPathError(f"no direct flight between {a!r} and {b!r}")
        ca, cb = net.cities[a], net.cities[b]
        d = point_distance(ca.x, ca.y, cb.x, cb.y, ctx)
        legs.append(Leg(a, b, stored(d, ctx)))
        total = d if total is None else ctx.add(total, d)
    assert total is not None
    price = ctx.multiply(total, PRICE_PER_KM)
    return Priced(cities, tuple(legs), stored(total, ctx), stored(price, ctx))


def _grouped(value: str, quantum: Decimal) -> str:
    """Round half up to `quantum` in the canonical context, then add thousands separators."""
    rounded = Decimal(value).quantize(quantum, rounding=ROUND_HALF_UP, context=new_context())
    return format(rounded, ",f")  # already rounded: formatting only inserts the commas


def fmt_km(distance: str) -> str:
    """Display only: 1 decimal place, half up, thousands separators. '8928.568…' -> '8,928.6 km'."""
    return f"{_grouped(distance, _Q_KM)} km"


def fmt_usd(price: str) -> str:
    """Display only: cents, half up, thousands separators. '1160.713…' -> '$1,160.71'."""
    return f"${_grouped(price, _Q_CENT)}"

"""Model-based test of the booking rules B1-B7 and Q1-Q3 (docs/design/state_invariants.md).

Seeded random event sequences run against the real `Airline` (own app.db, own copy of a locations
database, fake clock) and against a small reference model kept here. After EVERY event:

- the outcome of the event equals what the model predicted (error code, card state), and
- every invariant is checked on the rows of app.db.

The model decides independently of app code: time with its own arithmetic, freshness (B6) with
tests/reference.py (own sqlite read, own Bellman-Ford, own Decimal arithmetic) on the database file
as it is at click time. Seeds are fixed, so every run executes the same sequences; a failing seed
is shrunk and printed as a list that can be pasted into REGRESSIONS.

Events are plain tuples with small integers that are resolved against the current state ("the
k-th most recent quote"), so any sub-sequence is still a valid sequence (needed for shrinking).
"""
from __future__ import annotations

import hashlib
import json
import random
import sqlite3
import threading
from datetime import timedelta
from decimal import Decimal

import pytest

from app.airline import Airline, BookingError
from app.core.network import NetworkDataError
from app.store import parse_iso, records

from .airline_helpers import World, assert_card, assert_message, fixture_schemas
from .reference import RefGraph

SCHEMAS = fixture_schemas()
TTL = timedelta(minutes=15)
OPEN = ("quoted", "presented")
TERMINAL = ("booked", "expired", "stale")
ALLOWED = {("quoted", "presented"), ("quoted", "expired"), ("presented", "booked"),
           ("presented", "expired"), ("presented", "stale")}
USER_TEXTS = ["yes, book it", "ok confirm", "book the ticket now", "no, do not book", "is it cheaper via H2?",
              "how far is that?", "go ahead", "cancel"]
CLOCK_STEPS = [1, 1, 5, 30, 30, 60, 60, 120, 300, 600, 840, 899, 900, 901, 0.5, 0.5]

SMALL_SEEDS = range(60)
SMALL_LENGTH = 120
REAL_SEEDS = range(10)
REAL_LENGTH = 100


# ------------------------------------------------------------------------------- events -------
def gen_event(rng: random.Random) -> tuple:
    kind = rng.choices(
        ["quote", "done", "drop", "user_message", "llm_request_booking", "click", "click_concurrent",
         "replay", "other_user_click", "clock", "db_change", "reconnect"],
        weights=[14, 16, 2, 5, 8, 20, 5, 4, 3, 9, 6, 8],
    )[0]
    r = lambda: rng.randrange(1000)  # noqa: E731
    if kind == "quote":
        return (kind, r(), r(), r())
    if kind in ("done", "drop", "reconnect"):
        return (kind, r())
    if kind == "user_message":
        return (kind, r(), r())
    if kind == "llm_request_booking":
        return (kind, r(), r())
    if kind == "click":
        return (kind, r(), rng.choice(["valid", "valid", "valid", "garbage", "other_quote", "empty", "none"]), r())
    if kind == "click_concurrent":
        return (kind, r(), rng.choice([2, 3, 4]), r())
    if kind in ("replay", "other_user_click"):
        return (kind, r(), r())
    if kind == "clock":
        return (kind, rng.choice(CLOCK_STEPS))
    return (kind, rng.choices(["leg_removed", "coord_moved", "unrelated", "file_replaced", "restore", "broken"],
                              weights=[4, 4, 4, 2, 4, 1])[0], r(), r())


def gen_sequence(seed: int, length: int) -> list[tuple]:
    rng = random.Random(seed)
    return [gen_event(rng) for _ in range(length)]


# ------------------------------------------------------------------------------- the model ----
class MQuote:
    def __init__(self, qid, user, conv, created, cities, coords, distance, price):
        self.id, self.user, self.conv = qid, user, conv
        self.created = created  # floored to the second
        self.expires = created + TTL
        self.cities, self.coords, self.distance, self.price = cities, coords, distance, price
        self.status = "quoted"
        self.presented_at = None
        self.nonces: dict[str, str] = {}  # message id -> nonce the client was given
        self.ticket = None
        self.booked_by = None  # (event index, event kind, user index, clock)


class Sim:
    """The system under test plus the reference model, driven by the same events."""

    def __init__(self, tmp_path, real=False, airline_cls=Airline, **airline_kwargs):
        self.w = World(tmp_path, real=real, airline_cls=airline_cls, **airline_kwargs)
        w = self.w
        self.air = w.airline
        self.users = [w.alice, w.bob]
        self.convs = [(0, w.conv), (1, w.bob_conv),
                      (0, w.store.create_conversation(w.alice)["id"]),
                      (1, w.store.create_conversation(w.bob)["id"])]
        self.original = w.db.read_bytes()
        self.version = 0  # bumped on every change of the locations file
        self._ref: tuple[int, RefGraph] | None = None
        self._best: dict = {}
        ref = self.ref()
        if real:
            spokes = [c for c in ref.xy if c not in ref.hubs and ref.served(c)]
            hubs = [c for c in ref.xy if c in ref.hubs]
            unserved = [c for c in ref.xy if not ref.served(c)]
            self.names = (spokes[:5] + hubs[:3]) * 3 + unserved[:1] + ["Nowhere"]
        else:
            # mostly the connected part (A B C D H1-H4), now and then U, the island, a typo
            self.names = [n for n in ref.xy if n in "ABCD" or n.startswith("H")] * 3 + list(ref.xy) + ["Nowhere"]
        self.broken = False
        self.quotes: list[MQuote] = []
        self.by_id: dict[str, MQuote] = {}
        self.pending: dict[int, list] = {i: [] for i in range(len(self.convs))}
        self.raw_status: dict[str, str] = {}
        self.final: dict[str, str] = {}  # quote id -> terminal status once seen (Q3)
        self.index = -1
        self.kind = ""
        self.con = sqlite3.connect(w.store.path)  # one read connection for the invariant checks

    def sql(self, query, args=()):
        return self.con.execute(query, args).fetchall()

    def close(self):
        self.con.close()

    # --- independent facts about the locations file ---
    def ref(self) -> RefGraph:
        if self._ref is None or self._ref[0] != self.version:
            self._ref = (self.version, RefGraph.from_db(self.w.db))
            self._best = {}
        return self._ref[1]

    def best(self, origin, dest):
        ref = self.ref()
        if origin not in self._best:
            self._best[origin] = ref.bellman_ford_from(origin) if origin in ref.xy else {}
        return self._best[origin].get(dest)

    def fresh(self, q: MQuote) -> bool:
        """B6, decided without app code: same coordinates, every leg still a flight, transfers
        still hubs, and the reference's cheapest route is this itinerary at this price."""
        if self.broken:
            return False
        ref = self.ref()
        for city in q.cities:
            if city not in ref.xy or ref.xy[city] != q.coords[city]:
                return False
        if any(b not in ref.flights_from(a) for a, b in zip(q.cities, q.cities[1:])):
            return False
        if any(c not in ref.hubs for c in q.cities[1:-1]):
            return False
        best = self.best(q.cities[0], q.cities[-1])
        return (best is not None and best["cities"] == tuple(q.cities)
                and best["price"] == q.price and best["distance"] == q.distance)

    def mstatus(self, q: MQuote) -> str:
        if q.status in OPEN and self.w.clock.now >= q.expires:
            q.status = "expired"
        return q.status

    def expect_click(self, q: MQuote, user: int, nonce) -> str:
        if q.user != user:
            return "not_found"
        status = self.mstatus(q)
        if status == "booked":
            return "already_booked"
        if status in ("expired", "stale"):
            return status
        if status == "quoted":
            return "not_presented"
        if nonce not in q.nonces.values():
            return "invalid_nonce"
        if not self.fresh(q):
            q.status = "stale"
            return "stale"
        q.status = "booked"
        return "booked"

    # --- picking things ---
    def pick_quote(self, k: int) -> MQuote | None:
        if not self.quotes:
            return None
        return self.quotes[-1 - (k % min(len(self.quotes), 5))]

    def known_nonce(self, q: MQuote, k: int):
        values = list(q.nonces.values())
        return values[k % len(values)] if values else "n_never_given"

    # --- events ---
    def apply(self, index: int, event: tuple) -> None:
        self.index, self.kind = index, event[0]
        tickets_before = self.ticket_rows()
        getattr(self, "ev_" + event[0])(*event[1:])
        self.check_invariants(tickets_before)

    def ev_quote(self, c, o, d):
        user, conv = self.convs[c % len(self.convs)]
        origin, dest = self.names[o % len(self.names)], self.names[d % len(self.names)]
        before = self.raw_rows()
        try:
            result = self.air.quote_route(self.users[user], conv, origin, dest)
        except NetworkDataError:
            assert self.broken, "quote_route failed on a valid database"
            assert self.raw_rows() == before
            return
        assert not self.broken, "quote_route answered from a broken database"
        after = self.raw_rows()
        for card in result.cards:
            assert_card(card, SCHEMAS)
        assert "nonce\": \"" not in json.dumps([result.data, result.cards])
        if not result.ok:
            assert after == before, "a failed quote changed app.db"
            self.pending[c % len(self.convs)] += result.cards
            return
        card = result.cards[0]
        qid = card["id"]
        # Q1: creating a quote changes no other quote
        assert {k: v for k, v in after.items() if k != qid} == before, "Q1: another quote changed"
        assert after[qid] == "quoted", f"B2: a new quote is {after[qid]} before done"
        assert card["state"] == {"status": "quoted", "bookable": False, "nonce": None, "ticket_id": None}, card
        ref = self.ref()
        cities = [card["legs"][0]["from"]] + [leg["to"] for leg in card["legs"]]
        best = self.best(cities[0], cities[-1])
        assert best is not None and best["cities"] == tuple(cities), (cities, best)
        assert (card["price"], card["distance"]) == (best["price"], best["distance"])
        created = self.w.clock.now.replace(microsecond=0)
        q = MQuote(qid, user, c % len(self.convs), created, cities,
                   {city: ref.xy[city] for city in cities}, card["distance"], card["price"])
        assert parse_iso(card["expires_at"]) == q.expires
        trace = self.air.trace(self.users[user], qid)
        for leg in trace["legs"]:
            assert tuple(map(Decimal, map(str, leg["from_coord"]))) == q.coords[leg["from"]]
            assert tuple(map(Decimal, map(str, leg["to_coord"]))) == q.coords[leg["to"]]
        self.quotes.append(q)
        self.by_id[qid] = q
        self.pending[q.conv].append(card)

    def ev_done(self, c):
        ci = c % len(self.convs)
        user, conv = self.convs[ci]
        cards, self.pending[ci] = self.pending[ci], []
        expected = {}
        for card in cards:
            if card["type"] in ("quote", "booking_request"):
                q = self.by_id[card["id"]]
                if self.mstatus(q) == "quoted":
                    q.status = "presented"
                    q.presented_at = self.w.clock.now
                expected[q.id] = q.status
        message = self.air.post_assistant_message(self.users[user], conv, "Here is what I found.", cards)
        assert_message(message, SCHEMAS)
        assert len(message["cards"]) == len(cards)
        self.see_cards(message)

    def ev_drop(self, c):
        """The stream died before `done`: its cards were never presented."""
        self.pending[c % len(self.convs)] = []

    def ev_user_message(self, c, t):
        _, conv = self.convs[c % len(self.convs)]
        self.w.store.add_message(conv, "user", USER_TEXTS[t % len(USER_TEXTS)])

    def ev_llm_request_booking(self, c, k):
        ci = c % len(self.convs)
        user, conv = self.convs[ci]
        q = self.pick_quote(k)
        qid = q.id if q else "q_invented_by_the_llm"
        if q is None or q.user != user or q.conv != ci:
            expected = "not_found"
        else:
            expected = {"booked": "already_booked", "expired": "quote_expired", "stale": "stale",
                        "quoted": "ok", "presented": "ok"}[self.mstatus(q)]
        result = self.air.request_booking(self.users[user], conv, qid)
        assert result.code == expected, (result.code, expected)
        for card in result.cards:
            assert_card(card, SCHEMAS)
            if "state" in card:
                assert card["state"]["nonce"] is None and card["state"]["bookable"] is False
        if q is not None:
            for nonce in q.nonces.values():
                assert nonce not in json.dumps([result.data, result.cards]), "a tool result leaked a nonce"
        self.pending[ci] += result.cards

    def ev_click(self, k, nonce_kind, n, user=None):
        q = self.pick_quote(k)
        if q is None:
            return
        if nonce_kind == "valid":
            nonce = self.known_nonce(q, n)
        elif nonce_kind == "other_quote":
            others = [v for o in self.quotes if o is not q and o.user == q.user for v in o.nonces.values()]
            nonce = others[n % len(others)] if others else "n_no_other_quote"
        else:
            nonce = {"garbage": f"n_{n:032x}", "empty": "", "none": None}[nonce_kind]
        self.click(q, q.user if user is None else user, nonce)

    def ev_replay(self, k, n):
        """Click again with a nonce of a quote that is already booked."""
        booked = [q for q in self.quotes if q.status == "booked"]
        if booked:
            q = booked[k % len(booked)]
            self.click(q, q.user, self.known_nonce(q, n))

    def ev_other_user_click(self, k, n):
        q = self.pick_quote(k)
        if q is not None:
            self.click(q, 1 - q.user, self.known_nonce(q, n))

    def click(self, q: MQuote, user: int, nonce):
        expected = self.expect_click(q, user, nonce)
        try:
            out = self.air.book(self.users[user], q.id, nonce)
            got = "booked"
        except BookingError as exc:
            got = exc.code
            if got == "already_booked":
                assert exc.ticket_id == q.ticket
        assert got == expected, f"click on {q.id}: got {got}, the model says {expected}"
        if got == "booked":
            self.booked(q, user, out)

    def booked(self, q: MQuote, user: int, out: dict):
        ticket = out["ticket"]
        assert_card(ticket, SCHEMAS)
        assert_message(out["message"], SCHEMAS)
        q.ticket = ticket["id"]
        q.booked_by = (self.index, self.kind, user, self.w.clock.now)
        # B6: the ticket equals an independent recomputation on the file as it is right now
        best = self.best(q.cities[0], q.cities[-1])
        assert [ticket["legs"][0]["from"]] + [leg["to"] for leg in ticket["legs"]] == list(best["cities"])
        row = self.sql("select distance, price, network_fingerprint from tickets where id = ?", (ticket["id"],))
        digest = hashlib.sha256(self.w.db.read_bytes()).hexdigest()
        assert row == [(best["distance"], best["price"], f"sha256:{digest}")], "B6"

    def ev_click_concurrent(self, k, threads, n):
        q = self.pick_quote(k)
        if q is None:
            return
        nonce = self.known_nonce(q, n)
        expected = self.expect_click(q, q.user, nonce)
        barrier = threading.Barrier(threads)
        outcomes: list = [None] * threads

        def go(i):
            barrier.wait(10)
            try:
                outcomes[i] = self.air.book(self.users[q.user], q.id, nonce)
            except BookingError as exc:
                outcomes[i] = exc.code
            except Exception as exc:  # pragma: no cover - shown by the assertion below
                outcomes[i] = repr(exc)

        pool = [threading.Thread(target=go, args=(i,)) for i in range(threads)]
        for t in pool:
            t.start()
        for t in pool:
            t.join(30)
        wins = [o for o in outcomes if isinstance(o, dict)]
        codes = sorted(o for o in outcomes if not isinstance(o, dict))
        if expected == "booked":
            assert len(wins) == 1 and codes == ["already_booked"] * (threads - 1), outcomes  # B5
            self.booked(q, q.user, wins[0])
        else:
            assert not wins and codes == [expected] * threads, (outcomes, expected)

    def ev_clock(self, seconds):
        self.w.clock.advance(seconds=seconds)

    def ev_reconnect(self, c):
        """The client reloads the conversation: what it sees is the server state (Q2)."""
        user, conv = self.convs[c % len(self.convs)]
        for message in self.air.messages(self.users[user], conv):
            assert_message(message, SCHEMAS)
            self.see_cards(message)

    def see_cards(self, message):
        """Q2: every quote card a client receives carries the model's status; it is bookable
        exactly when the quote is presented, always with the same nonce for the same card."""
        for card in message["cards"]:
            if card["type"] not in ("quote", "booking_request"):
                continue
            q = self.by_id[card["id"]]
            status = self.mstatus(q)
            state = card["state"]
            assert state["status"] == status, f"Q2: card says {state['status']}, model {status}"
            assert state["bookable"] is (status == "presented"), f"Q2: bookable on a {status} quote"
            assert (state["nonce"] is not None) is state["bookable"]
            assert state["ticket_id"] == (q.ticket if status == "booked" else None)
            if state["nonce"] is not None:
                assert q.nonces.setdefault(message["id"], state["nonce"]) == state["nonce"], "nonce changed"
                for other in self.quotes:
                    assert other is q or state["nonce"] not in other.nonces.values(), "nonce reused"

    def ev_db_change(self, kind, a, b):
        w = self.w
        if kind == "restore":
            w.replace_db(self.original)
            self.broken = False
        elif kind == "file_replaced":
            w.replace_db(w.db.read_bytes())
        elif kind == "broken":
            w.edit_db("update locations set coordinate = 'oops' where rowid = 1")
            self.broken = True
        elif not self.broken:
            ref = self.ref()
            live = [q for q in self.quotes if q.status in OPEN]
            on_route = a % 5 < 3 and live
            if kind == "leg_removed":
                if on_route:
                    q = live[b % len(live)]
                    legs = list(zip(q.cities, q.cities[1:]))
                else:
                    legs = sorted((x, y) for x in ref.xy for y in ref.flights_from(x) if x < y)
                if legs:
                    self.remove_leg(*legs[(a // 5) % len(legs)])
            elif kind == "coord_moved":
                names = live[b % len(live)].cities if on_route else list(ref.xy)
                name = names[(a // 5) % len(names)]
                x, y = ref.xy[name]
                w.edit_db(("update locations set coordinate = ? where city_name = ?",
                           (f"{x + 1 + b % 3},{y}", name)))
            else:  # unrelated: a city without service moves; no route can be affected
                unserved = [c for c in ref.xy if not ref.served(c)]
                if unserved:
                    name = unserved[a % len(unserved)]
                    x, y = ref.xy[name]
                    w.edit_db(("update locations set coordinate = ? where city_name = ?", (f"{x},{y + 1}", name)))
                    self.version += 1
                    assert all(self.fresh(q) for q in live if self.was_fresh.get(q.id)), "unrelated change"
        self.version += 1

    def remove_leg(self, a, b):
        ref = self.ref()
        if a in ref.hubs and b in ref.hubs:
            self.w.edit_db(("delete from hub_links where (hub_a = ? and hub_b = ?) or (hub_a = ? and hub_b = ?)",
                            (a, b, b, a)))
        else:
            spoke, hub = (b, a) if a in ref.hubs else (a, b)
            left = ";".join(h for h in ref.spokes[spoke] if h != hub)
            self.w.edit_db(("update locations set connected_hubs = ? where city_name = ?", (left, spoke)))

    # --- invariants, checked on app.db after every event ---
    def raw_rows(self) -> dict:
        return dict(self.sql("select id, status from quotes"))

    def ticket_rows(self) -> dict:
        rows = self.sql("select quote_id, id, user_id, legs_snapshot, distance, price, booked_at, "
                          "confirmed_message_id from tickets")
        assert len({r[0] for r in rows}) == len(rows), "B5: two tickets for one quote"
        return {r[0]: r[1:] for r in rows}

    def check_invariants(self, tickets_before: dict) -> None:
        now = self.w.clock.now
        tickets = self.ticket_rows()  # B5 inside
        quotes = {r[0]: r for r in self.sql(
            "select id, user_id, status, legs, distance, price, created_at, expires_at, presented_at from quotes")}
        assert set(quotes) == set(self.by_id), "quotes in app.db differ from the model"

        # B3: tickets appear only through a click, and exactly where the model says so
        new = set(tickets) - set(tickets_before)
        assert not (set(tickets_before) - set(tickets)), "a ticket disappeared"
        assert all(tickets[k] == tickets_before[k] for k in tickets_before), "a ticket changed"
        if self.kind not in ("click", "click_concurrent", "replay", "other_user_click"):
            assert not new, f"B3: {self.kind} created a ticket"
        assert set(tickets) == {q.id for q in self.quotes if q.status == "booked"}, "B3: tickets differ from the model"
        # B7: booked <=> exactly one ticket
        assert {qid for qid, row in quotes.items() if row[2] == "booked"} == set(tickets), "B7"

        for qid, (tid, user_id, legs, distance, price, booked_at, message_id) in tickets.items():
            q, row = self.by_id[qid], quotes[qid]
            index, kind, clicker, clicked_at = q.booked_by
            assert tid == q.ticket and kind in ("click", "click_concurrent", "replay"), "B3"
            assert user_id == row[1] == self.users[q.user] == self.users[clicker], "B1"
            assert q.presented_at is not None and q.presented_at <= clicked_at and row[8] is not None, "B2"
            assert message_id in q.nonces, "B3: not confirmed through a card the client was given"
            assert clicked_at < q.expires and parse_iso(booked_at) < parse_iso(row[7]), "B4"
            assert parse_iso(booked_at) - parse_iso(row[6]) < TTL, "B4"
            assert (json.loads(legs), distance, price) == (json.loads(row[3]), row[4], row[5]), "B6: ticket != quote"
            assert (distance, price) == (q.distance, q.price), "B6"

        for qid, row in quotes.items():
            q = self.by_id[qid]
            raw = row[2]
            # status only moves along the edges of the design's state machine; terminal stays (Q3)
            previous = self.raw_status.get(qid, "quoted")
            assert raw == previous or (previous, raw) in ALLOWED, f"Q3: {previous} -> {raw}"
            self.raw_status[qid] = raw
            effective = "expired" if raw in OPEN and now >= parse_iso(row[7]) else raw
            expected = self.mstatus(q)
            assert effective == expected, f"{qid}: app.db says {effective}, the model {expected}"
            if qid in self.final:
                assert effective == self.final[qid], f"Q3: {self.final[qid]} became {effective}"
            elif effective in TERMINAL:
                self.final[qid] = effective
        # the API view agrees with the rows (Q2), for the quotes a client is most likely to hold
        for q in self.quotes[-1:]:
            card = self.air.get_quote(self.users[q.user], q.id)
            assert card["state"]["status"] == q.status, f"Q2: view says {card['state']['status']}, model {q.status}"
            assert card["state"]["nonce"] is None, "a nonce outside a presented message card"
            assert self.air.get_quote(self.users[1 - q.user], q.id) is None, "another user can read the quote"

    @property
    def was_fresh(self) -> dict:
        return self._was_fresh

    def remember_freshness(self):
        self._was_fresh = {} if self.broken else {q.id: self.fresh(q) for q in self.quotes if q.status in OPEN}


def _apply_with_memory(sim: Sim, index: int, event: tuple) -> None:
    if event[0] == "db_change" and event[1] == "unrelated":
        sim.remember_freshness()
    sim.apply(index, event)


def run(sequence, tmp_path, **sim_kwargs) -> Sim:
    sim = Sim(tmp_path, **sim_kwargs)
    try:
        for index, event in enumerate(sequence):
            try:
                _apply_with_memory(sim, index, event)
            except AssertionError as exc:
                raise AssertionError(f"event {index} {event}: {exc}") from exc
    finally:
        sim.close()
    return sim


def shrink(sequence, fails):
    """Remove chunks, then single events, while the sequence still fails (tool/model_check.py)."""
    n = 2
    while len(sequence) >= 2:
        chunk = max(1, len(sequence) // n)
        for start in range(0, len(sequence), chunk):
            candidate = sequence[:start] + sequence[start + chunk:]
            if fails(candidate):
                sequence, n = candidate, max(n - 1, 2)
                break
        else:
            if chunk == 1:
                break
            n = min(n * 2, len(sequence))
    return sequence


def check(seeds, length, dirs, **sim_kwargs):
    """Run every seed; on the first failure shrink it and report a pasteable regression case."""
    def failure(sequence):
        try:
            run(sequence, dirs.mktemp("model"), **sim_kwargs)
        except Exception as exc:  # any crash of the system is a failure too
            return exc
        return None

    for seed in seeds:
        sequence = gen_sequence(seed, length)
        if failure(sequence) is None:
            continue
        small = shrink(sequence, lambda s: failure(s) is not None)
        raise AssertionError(f"seed {seed} fails: {failure(small)!r}\nkeep as a named case in REGRESSIONS:\n{small!r}")


